SELECT cost_bucket, kerry_cost, carrier_values FROM (SELECT CASE WHEN cost >= 96 THEN 'high' WHEN cost >= 18 THEN 'mid' ELSE 'low' END AS cost_bucket, SUM(CASE WHEN carrier = 'Kerry' THEN cost ELSE 0 END) AS kerry_cost, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(carrier))) AS carrier_values FROM shipments WHERE delivered_date <= '2023-06-24' GROUP BY CASE WHEN cost >= 96 THEN 'high' WHEN cost >= 18 THEN 'mid' ELSE 'low' END) AS x WHERE kerry_cost >= 63 ORDER BY carrier_values DESC;
